import sys, json, time, random
sys.dont_write_bytecode = True
sys.path.insert(0, sys.argv[0].rsplit("/", 1)[0])
from gate3 import configure
snap, tmp, workload = sys.argv[1], sys.argv[2], sys.argv[3]
sd, ns, post = configure(snap, tmp, workload, real_ladder=(workload == "real"))
if workload == "py":
    def busy(meshes, model, write, t0, levels, after_level=None):
        write("level0.json", {"level": 0})
        print("READY", flush=True)
        while True:
            pass
    sd.run_levels = busy
else:
    real_solve = ns.solve
    state = {"ready": False}
    def solve(*a, **k):
        if not state["ready"]:
            state["ready"] = True
            print("READY", flush=True)
        return real_solve(*a, **k)
    sd.ns.solve = solve
sys.exit(sd.main([]))

