import json, os, signal, subprocess, sys, tempfile, time
from pathlib import Path
HERE = Path(__file__).resolve().parent
PY = "/home/user/QMHP-CEM/.venv/bin/python"
ENV = {**os.environ, "OPENBLAS_NUM_THREADS": "1", "OMP_NUM_THREADS": "1", "MKL_NUM_THREADS": "1", "PYTHONDONTWRITEBYTECODE": "1"}
S = "/tmp/claude-0/-home-user-QMHP-CEM/7e301b81-9cc3-5878-8c8a-f1390dcdb988/scratchpad"

def state(tmp):
    tmp = Path(tmp)
    out = {}
    for name, p in (("marker", tmp / "ATTEMPT-SPENT.json"),
                    ("common_ledger", tmp / "gitcommon" / "qmhp-attempts" / "STATIC-REFINEMENT-STUDY.json")):
        if p.exists():
            txt = p.read_text()
            try:
                j = json.loads(txt)
                out[name] = {"size": len(txt), "record_created": j.get("record_created"), "error": (j.get("error") or "")[:120],
                             "verdict": (j.get("verdict") or "")[:60]}
            except ValueError:
                out[name] = {"size": len(txt), "unparseable": True}
    out["approval_left"] = (tmp / "STUDY-APPROVAL.json").exists()
    out["approval_consumed"] = (tmp / "STUDY-APPROVAL.consumed.json").exists()
    recs = []
    for root in (tmp / "results", tmp / "afile" / "results"):
        if root.is_dir():
            recs += [p.name for p in root.iterdir()]
    out["records"] = recs
    return out

for snap in ("review-9aa951fae23c413c47518e2c4f3bfed8096c4f4d", "review-3270469"):
    for mode, sig in (("norecord", None), ("window", "SIGTERM"), ("window", "SIGINT")):
        tmp = tempfile.mkdtemp(prefix=f"gap-{mode}-{sig}-", dir=str(HERE / "trials"))
        p = subprocess.Popen([PY, "-B", str(HERE / "gap_child.py"), f"{S}/{snap}", tmp, mode], stdout=subprocess.PIPE,
                             stderr=subprocess.PIPE, text=True, env=ENV, cwd=str(HERE))
        if sig:
            line = p.stdout.readline().strip()
            time.sleep(0.3)
            os.kill(p.pid, getattr(signal, sig))
        else:
            line = None
        out, err = p.communicate(timeout=120)
        st = state(tmp)
        # the second run: must refuse (exit 2) with nothing more spent
        tmp2 = tmp
        p2 = subprocess.run([PY, "-B", str(HERE / "gap_child.py"), f"{S}/{snap}", tmp2, "second"], capture_output=True, text=True, env=ENV, cwd=str(HERE), timeout=120)
        print(json.dumps({"snapshot": snap[:14], "mode": mode, "signal": sig, "window_line": line, "rc": p.returncode,
                          "stderr_last": err.strip().splitlines()[-1:] if err.strip() else [], "state": st,
                          "second_run_rc": p2.returncode, "second_run_stderr": p2.stderr.strip().splitlines()[-1:]}))
